import React, { useEffect, useMemo, useState } from 'react';
import { Card } from '@material-ui/core';
import Table from '@material-ui/core/Table';
import TableBody from '@material-ui/core/TableBody';
import TableCell from '@material-ui/core/TableCell';
import TableHead from '@material-ui/core/TableHead';
import TableRow from '@material-ui/core/TableRow';
import NativeSelect from '@material-ui/core/NativeSelect';
import { Row, Col } from 'reactstrap';
import CustomButton from 'components/CustomButton';
import CustomInput from 'views/admin/Common/CustomInput';
import EmptyState from 'views/admin/Common/EmptyState';
import StatTile from 'views/admin/Common/StatTile';
import { SkeletonRows } from 'views/admin/Common/Loader';
import colors from 'config/colors';
import { courseStatic } from 'config/constants';
import { PLAN_ACTIONS, PLAN_ACTION_LABELS, RUN_STATUS, planCounts, planItemBody } from 'utils/promotion';
import { ActionChip } from './StatusChip';
import ScrollTable from './ScrollTable';
import StepHeader from './StepHeader';

const PAGE = 50;

const intro =
  'Generate the plan to see where every student goes. Nothing is moved yet: change anyone who should be treated differently, then apply it in the last step.';

const itemName = item => item.studentName || `Student ${item.studentId}`;

// Step 3: the plan - a count per class, and the student by student list of the class picked there.
const PlanStep = ({
  run,
  plan,
  planLoading,
  planCourseId,
  onPickCourse,
  onGenerate,
  generating,
  courses,
  onSaveItem,
  savingItemId,
  askConfirm,
  goToStep,
}) => {
  const [drafts, setDrafts] = useState({});
  const [search, setSearch] = useState('');
  const [shown, setShown] = useState(PAGE);
  useEffect(() => setDrafts({}), [plan]);
  useEffect(() => setShown(PAGE), [plan, search, planCourseId]);

  const editable = run?.status === RUN_STATUS.planReady;
  const counts = useMemo(() => planCounts(plan), [plan]);
  const items = useMemo(() => {
    const needle = search.trim().toLowerCase();
    const all = plan?.items || [];
    return needle ? all.filter(item => itemName(item).toLowerCase().includes(needle)) : all;
  }, [plan, search]);

  if (!run) {
    return (
      <Card className="p-3 text-center">
        <div style={{ padding: 20, color: '#6b778a' }}>Create the new batch first (step 2) before the plan.</div>
        <CustomButton name="Go to New batch" onClick={() => goToStep(1)} style={{ margin: '0 auto' }} />
      </Card>
    );
  }

  const draftOf = item => drafts[item.itemId] || { action: item.action, toCourseId: item.toCourseId ?? '' };
  const setDraft = (item, patch) => setDrafts(prev => ({ ...prev, [item.itemId]: { ...draftOf(item), ...patch } }));
  const changed = item => {
    const draft = draftOf(item);
    return draft.action !== item.action || String(draft.toCourseId ?? '') !== String(item.toCourseId ?? '');
  };
  const pickedClass = (plan?.summary || []).find(row => row.fromCourseId === planCourseId);

  const regenerate = () =>
    askConfirm('Generate the plan again? The changes you made to students in the current plan are lost.', onGenerate);

  return (
    <>
      <Card className="p-3 mb-3">
        <StepHeader title="Review plan" intro={intro} />
        {!plan && !planLoading ? (
          <div className="d-flex align-items-center" style={{ gap: 12 }}>
            <CustomButton
              name="Generate plan"
              showLoader
              loading={generating}
              disabled={generating}
              onClick={onGenerate}
            />
            <span style={{ fontSize: 13, color: '#8b95a1' }}>
              Works out, for every student, the {courseStatic.toLowerCase()} they move up to.
            </span>
          </div>
        ) : planLoading && !plan ? (
          <div style={{ padding: 20 }}>
            <SkeletonRows rows={3} avatar={false} />
          </div>
        ) : (
          <>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 12 }}>
              <StatTile label="Students" value={plan.totalStudents ?? 0} />
              <StatTile label="Promote" value={counts.promote} tone="good" />
              <StatTile label="Graduate" value={counts.graduate} tone="info" />
              <StatTile label="Exclude" value={counts.exclude} tone="warn" />
              <StatTile
                label="Errors"
                value={plan.totalErrors ?? counts.error}
                tone={plan.totalErrors ? 'bad' : 'good'}
              />
            </div>
            {editable && (
              <div style={{ marginTop: 12 }}>
                <CustomButton
                  variant="outlined"
                  size="small"
                  name="Generate again"
                  showLoader
                  loading={generating}
                  disabled={generating}
                  onClick={regenerate}
                />
              </div>
            )}
          </>
        )}
      </Card>

      {!!plan && (
        <>
          <Card className="p-3 mb-3">
            <StepHeader
              title={`By ${courseStatic.toLowerCase()}`}
              intro={`Pick a ${courseStatic.toLowerCase()} to see its students below.`}
            />
            <ScrollTable maxHeight={360}>
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell>From {courseStatic.toLowerCase()}</TableCell>
                    <TableCell>To {courseStatic.toLowerCase()}</TableCell>
                    <TableCell align="right">Promote</TableCell>
                    <TableCell align="right">Graduate</TableCell>
                    <TableCell align="right">Exclude</TableCell>
                    <TableCell align="right">Error</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {(plan.summary || []).map(row => (
                    <TableRow
                      key={row.fromCourseId}
                      hover
                      selected={row.fromCourseId === planCourseId}
                      style={{ cursor: 'pointer' }}
                      onClick={() => onPickCourse(row.fromCourseId === planCourseId ? 0 : row.fromCourseId)}>
                      <TableCell style={{ fontWeight: 'bold' }}>{row.fromCourseName}</TableCell>
                      <TableCell>{row.toCourseId ? row.toCourseName : '-'}</TableCell>
                      <TableCell align="right">{row.promote}</TableCell>
                      <TableCell align="right">{row.graduate}</TableCell>
                      <TableCell align="right">{row.exclude}</TableCell>
                      <TableCell align="right" style={row.error ? { color: '#c62828', fontWeight: 'bold' } : undefined}>
                        {row.error}
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </ScrollTable>
          </Card>

          <Card className="p-3">
            <Row>
              <Col md={8}>
                <StepHeader
                  title="Students"
                  intro={
                    pickedClass
                      ? `Showing ${
                          pickedClass.fromCourseName
                        }. Pick the ${courseStatic.toLowerCase()} again to show every student.`
                      : `Every student of the school. Pick a ${courseStatic.toLowerCase()} above to see only its students.`
                  }
                />
              </Col>
              <Col md={4}>
                <CustomInput
                  name="search"
                  placeholder="Search a student..."
                  value={search}
                  onChange={(n, v) => setSearch(v)}
                />
              </Col>
            </Row>
            {planLoading ? (
              <div style={{ padding: 20 }}>
                <SkeletonRows rows={4} />
              </div>
            ) : !items.length ? (
              <EmptyState compact bare icon="fas fa-user-graduate" title="No students to show" />
            ) : (
              <>
                <ScrollTable maxHeight={560}>
                  <Table size="small" stickyHeader>
                    <TableHead>
                      <TableRow>
                        <TableCell>Student</TableCell>
                        <TableCell>From</TableCell>
                        <TableCell>To</TableCell>
                        <TableCell>Action</TableCell>
                        {editable && <TableCell>Change</TableCell>}
                      </TableRow>
                    </TableHead>
                    <TableBody>
                      {items.slice(0, shown).map(item => {
                        const draft = draftOf(item);
                        return (
                          <TableRow key={item.itemId} hover>
                            <TableCell>
                              <b>{itemName(item)}</b>
                              <span style={{ color: '#8b95a1', fontSize: 12 }}> ({item.studentId})</span>
                            </TableCell>
                            <TableCell>{item.fromCourseName}</TableCell>
                            <TableCell>{item.toCourseName || '-'}</TableCell>
                            <TableCell>
                              <ActionChip action={item.action} />
                              {!!item.message && (
                                <div style={{ color: item.action === 'ERROR' ? '#c62828' : '#6b778a', fontSize: 12 }}>
                                  {item.message}
                                </div>
                              )}
                            </TableCell>
                            {editable && (
                              <TableCell style={{ minWidth: 230 }}>
                                <NativeSelect
                                  value={draft.action === 'ERROR' ? '' : draft.action}
                                  onChange={e => setDraft(item, { action: e.target.value })}>
                                  {draft.action === 'ERROR' && <option value="">Fix this...</option>}
                                  {PLAN_ACTIONS.map(action => (
                                    <option key={action} value={action}>
                                      {PLAN_ACTION_LABELS[action]}
                                    </option>
                                  ))}
                                </NativeSelect>{' '}
                                {draft.action === 'PROMOTE' && (
                                  <NativeSelect
                                    value={draft.toCourseId ?? ''}
                                    onChange={e => setDraft(item, { toCourseId: e.target.value })}>
                                    <option value="">{`-- ${courseStatic.toLowerCase()} --`}</option>
                                    {courses.map(course => (
                                      <option key={course.courseId} value={course.courseId}>
                                        {course.name}
                                      </option>
                                    ))}
                                  </NativeSelect>
                                )}{' '}
                                <CustomButton
                                  size="small"
                                  name="Save"
                                  showLoader
                                  loading={savingItemId === item.itemId}
                                  disabled={
                                    !changed(item) ||
                                    !!savingItemId ||
                                    !draft.action ||
                                    (draft.action === 'PROMOTE' && !draft.toCourseId)
                                  }
                                  onClick={() => onSaveItem(item.itemId, planItemBody(draft.action, draft.toCourseId))}
                                />
                              </TableCell>
                            )}
                          </TableRow>
                        );
                      })}
                    </TableBody>
                  </Table>
                </ScrollTable>
                {items.length > shown && (
                  <div style={{ textAlign: 'center', padding: '10px 0', fontSize: 13, color: '#6b778a' }}>
                    Showing {shown} of {items.length}.{' '}
                    <a
                      style={{ color: colors.aTag, cursor: 'pointer', fontWeight: 'bold' }}
                      onClick={() => setShown(prev => prev + PAGE)}>
                      Show more
                    </a>
                  </div>
                )}
              </>
            )}
            {!editable && (
              <div style={{ marginTop: 8, fontSize: 12, color: '#8b95a1' }}>
                The promotion is done, so the plan can no longer be changed. Revert the promotion to change it.
              </div>
            )}
          </Card>
        </>
      )}
    </>
  );
};

export default PlanStep;
