import axios from 'axios';
import constants from '../../config/constants';

// Student promotion (the year-end rollover): set each class's next class, create the new batch, review a plan of who
// goes where, then apply it. Every call is under /api/promotion/{schoolId}; a run (a "promotion request") is one rollover
// from a source batch into a new batch, and moves BATCH_CREATED -> PLAN_READY -> PROMOTED.
const baseUrl = schoolId => `${constants.API_BASE_URL}/api/promotion/${schoolId}`;
const get = (url, token) => axios.get(url, constants.setHeader(token)).then(res => res.data);

// Batches of the school, and the active classes of one batch.
export const fetchPromotionBatchesApi = ({ token, schoolId }) => get(`${baseUrl(schoolId)}/batches`, token);

export const fetchPromotionBatchCoursesApi = ({ token, schoolId, batchId }) =>
  get(`${baseUrl(schoolId)}/batches/${batchId}/courses`, token);

// Class order: one row per class, toCourseId null = the final class (its students graduate).
export const fetchCourseMapApi = ({ token, schoolId }) => get(`${baseUrl(schoolId)}/course-map`, token);

export const saveCourseMapApi = ({ token, schoolId, mapId, postData }) =>
  mapId
    ? axios.put(`${baseUrl(schoolId)}/course-map/${mapId}`, postData, constants.setHeader(token))
    : axios.post(`${baseUrl(schoolId)}/course-map`, postData, constants.setHeader(token));

export const deleteCourseMapApi = ({ token, schoolId, mapId }) =>
  axios.delete(`${baseUrl(schoolId)}/course-map/${mapId}`, constants.setHeader(token));

export const verifyCourseMapApi = ({ token, schoolId, sourceBatchId }) =>
  get(`${baseUrl(schoolId)}/course-map/verify?sourceBatchId=${sourceBatchId}`, token);

// Promotion requests.
export const fetchPromotionRunsApi = ({ token, schoolId }) => get(`${baseUrl(schoolId)}/runs`, token);

export const fetchPromotionRunApi = ({ token, schoolId, runId }) => get(`${baseUrl(schoolId)}/runs/${runId}`, token);

export const createPromotionRunApi = ({ token, schoolId, postData }) =>
  axios.post(`${baseUrl(schoolId)}/runs`, postData, constants.setHeader(token)).then(res => res.data);

// The plan: who is promoted, graduates or is left out. Generating it again replaces the old one (and any edits).
export const generatePromotionPlanApi = ({ token, schoolId, runId }) =>
  axios.post(`${baseUrl(schoolId)}/runs/${runId}/plan`, undefined, constants.setHeader(token)).then(res => res.data);

export const fetchPromotionPlanApi = ({ token, schoolId, runId, courseId }) =>
  get(`${baseUrl(schoolId)}/runs/${runId}/plan${courseId ? `?courseId=${courseId}` : ''}`, token);

export const updatePromotionPlanItemApi = ({ token, schoolId, runId, itemId, postData }) =>
  axios.put(`${baseUrl(schoolId)}/runs/${runId}/plan/${itemId}`, postData, constants.setHeader(token));

export const applyPromotionRunApi = ({ token, schoolId, runId }) =>
  axios.post(`${baseUrl(schoolId)}/runs/${runId}/apply`, undefined, constants.setHeader(token)).then(res => res.data);

// Undoes the latest finished step. When that was the first one the whole request is removed and nothing comes back.
export const revertPromotionRunApi = ({ token, schoolId, runId }) =>
  axios.post(`${baseUrl(schoolId)}/runs/${runId}/revert`, undefined, constants.setHeader(token)).then(res => res.data);
