import React from 'react';
import { TONE_COLORS } from 'views/admin/Common/StatTile';
import { PLAN_ACTION_LABELS } from 'utils/promotion';

const STATUS = {
  BATCH_CREATED: { label: 'Batch created', tone: 'warn' },
  PLAN_READY: { label: 'Plan ready', tone: 'info' },
  PROMOTED: { label: 'Promoted', tone: 'good' },
  LEGACY: { label: 'Old process', tone: 'neutral' },
};
const ACTION_TONE = { PROMOTE: 'good', GRADUATE: 'info', EXCLUDE: 'warn', ERROR: 'bad' };

export const Chip = ({ label, tone }) => {
  const color = TONE_COLORS[tone] || TONE_COLORS.neutral;
  return (
    <span
      style={{
        display: 'inline-block',
        border: `1px solid ${color}66`,
        background: `${color}14`,
        color,
        borderRadius: 2,
        fontSize: 12,
        fontWeight: 'bolder',
        padding: '2px 10px',
        whiteSpace: 'nowrap',
      }}>
      {label}
    </span>
  );
};

// A request's status (Batch created / Plan ready / Promoted) in the same chip look as Active / Inactive.
const StatusChip = ({ status }) => {
  const item = STATUS[status];
  return <Chip label={item?.label || status || '--'} tone={item?.tone || 'neutral'} />;
};

// What the plan does with one student (Promote / Graduate / Exclude, or Error when it cannot be done).
export const ActionChip = ({ action }) => (
  <Chip label={PLAN_ACTION_LABELS[action] || action || '--'} tone={ACTION_TONE[action] || 'neutral'} />
);

export default StatusChip;
