import React from 'react';
import { Card } from '@material-ui/core';
import { Row, Col } from 'reactstrap';
import CheckCircleIcon from '@material-ui/icons/CheckCircle';
import CustomButton from 'components/CustomButton';
import StatTile from 'views/admin/Common/StatTile';
import { courseStatic } from 'config/constants';
import colors from 'config/colors';
import { RUN_STATUS, planCounts } from 'utils/promotion';
import StepHeader from './StepHeader';

// Step 4: apply the plan (the students move into the new batch), or see the result of a finished promotion.
const PromoteStep = ({
  run,
  plan,
  targetName,
  onApply,
  applying,
  askConfirm,
  goToStep,
  onStartAgain,
  onOpenStudents,
}) => {
  if (!run) {
    return (
      <Card className="p-3 text-center">
        <div style={{ padding: 20, color: '#6b778a' }}>Create the new batch and review the plan before promoting.</div>
        <CustomButton name="Go to New batch" onClick={() => goToStep(1)} style={{ margin: '0 auto' }} />
      </Card>
    );
  }

  if (run.status === RUN_STATUS.created) {
    return (
      <Card className="p-3 text-center">
        <div style={{ padding: 20, color: '#6b778a' }}>Generate and review the plan first.</div>
        <CustomButton name="Go to Review plan" onClick={() => goToStep(2)} style={{ margin: '0 auto' }} />
      </Card>
    );
  }

  const counts = planCounts(plan);
  const total = plan?.totalStudents ?? counts.promote + counts.graduate + counts.exclude + counts.error;

  if (run.status === RUN_STATUS.promoted) {
    return (
      <Card className="p-3 text-center">
        <CheckCircleIcon style={{ fontSize: 48, color: colors.accent }} />
        <h5 style={{ fontWeight: 'bold' }}>{run.academicName} is ready</h5>
        <div style={{ color: '#6b778a', marginBottom: 16 }}>
          The students are in {targetName || 'the new batch'}. Switch to it from the academic year at the top of the
          page.
        </div>
        <Row className="justify-content-center mb-3">
          <Col md={8} style={{ display: 'flex', flexWrap: 'wrap', gap: 12 }}>
            <StatTile label="Promoted" value={counts.promote} tone="good" />
            <StatTile label="Graduated" value={counts.graduate} tone="info" />
            <StatTile label="Excluded" value={counts.exclude} tone="warn" />
          </Col>
        </Row>
        <Row className="justify-content-center">
          <Col md={4}>
            <CustomButton name="Open students" onClick={onOpenStudents} fullWidth />
          </Col>
          <Col md={4}>
            <CustomButton variant="outlined" name="Start another promotion" onClick={onStartAgain} fullWidth />
          </Col>
        </Row>
      </Card>
    );
  }

  return (
    <Card className="p-3">
      <StepHeader
        title="Promote students"
        intro={`Applying the plan adds the students to ${
          targetName || 'the new batch'
        }. It can be reverted afterwards, unless something blocks it.`}
      />
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 12, marginBottom: 16 }}>
        <StatTile label="Students" value={total} />
        <StatTile
          label="Promote"
          value={counts.promote}
          tone="good"
          note={`to the next ${courseStatic.toLowerCase()}`}
        />
        <StatTile label="Graduate" value={counts.graduate} tone="info" />
        <StatTile label="Exclude" value={counts.exclude} tone="warn" />
        <StatTile label="Errors" value={counts.error} tone={counts.error ? 'bad' : 'good'} />
      </div>
      {counts.error > 0 && (
        <div style={{ color: '#c62828', fontSize: 13, marginBottom: 12 }}>
          {counts.error} student{counts.error > 1 ? 's have' : ' has'} an error in the plan.{' '}
          <a style={{ color: colors.aTag, cursor: 'pointer', fontWeight: 'bold' }} onClick={() => goToStep(2)}>
            Fix them in Review plan before promoting
          </a>
        </div>
      )}
      <CustomButton
        name="Promote students"
        showLoader
        loading={applying}
        disabled={applying || counts.error > 0}
        onClick={() =>
          askConfirm(`Apply the promotion? Students will be added to ${targetName || 'the new batch'}.`, onApply)
        }
      />
    </Card>
  );
};

export default PromoteStep;
