import React, { useEffect, useMemo, useRef, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useHistory, useLocation } from 'react-router-dom';
import Stepper from '@material-ui/core/Stepper';
import Step from '@material-ui/core/Step';
import StepButton from '@material-ui/core/StepButton';
import { Card, Button, LinearProgress } from '@material-ui/core';
import CheckCircleIcon from '@material-ui/icons/CheckCircle';
import CustomButton from 'components/CustomButton';
import constants, { courseStatic } from 'config/constants';
import { store } from 'index';
import { showToast } from 'actions/admin/auth';
import { fetchSchoolBatchsService } from 'actions/admin/batches';
import {
  applyPromotionRunApi,
  createPromotionRunApi,
  deleteCourseMapApi,
  fetchCourseMapApi,
  fetchPromotionBatchCoursesApi,
  fetchPromotionBatchesApi,
  fetchPromotionPlanApi,
  fetchPromotionRunApi,
  fetchPromotionRunsApi,
  generatePromotionPlanApi,
  revertPromotionRunApi,
  saveCourseMapApi,
  updatePromotionPlanItemApi,
  verifyCourseMapApi,
} from 'actions/admin/promotion';
import { formResMessage, getCurrentYearBatchUtils, getGlobalSchoolUtils } from 'utils/commonFunc';
import { decodeUrlId, encodeUrlId } from 'utils/urlIdCodec';
import {
  RUN_STATUS,
  classOrderProgress,
  courseMapBody,
  doneSteps,
  indexCourseMap,
  openRunOf,
  revertLabel,
  revertMessage,
  sortByClassOrder,
  stepOfRun,
  suggestNextBatch,
} from 'utils/promotion';
import ConfirmModal from 'views/admin/Common/ConfirmModal';
import EmptyState from 'views/admin/Common/EmptyState';
import ClassOrderStep from './components/ClassOrderStep';
import NewBatchStep from './components/NewBatchStep';
import PlanStep from './components/PlanStep';
import PromoteStep from './components/PromoteStep';
import StatusChip from './components/StatusChip';

const steps = [`${courseStatic} order`, 'New batch', 'Review plan', 'Promote'];
const clampStep = n => Math.min(Math.max(Number(n) || 0, 0), steps.length - 1);

const toastError = err => store.dispatch(showToast(formResMessage(err), 'error'));
const toast = (message, type = 'success') => store.dispatch(showToast(message, type));

// The year-end promotion: set each class's next class, create the new batch, review the plan, then move the students.
// A guided page like New Academic Year - every step can be opened any time - over the school's promotion requests, so a
// request that is half done can be carried on later from the "New batch" step.
const PromotionWizard = () => {
  const dispatch = useDispatch();
  const history = useHistory();
  const location = useLocation();
  const token = useSelector(state => state.auth.loggedUserToken);
  const schoolId = getGlobalSchoolUtils()?.schoolId;
  const api = { token, schoolId };

  const firstQuery = useRef(new URLSearchParams(location.search));
  const [activeStep, setActiveStep] = useState(() => clampStep(firstQuery.current.get('step')));
  const [sourceBatchId, setSourceBatchId] = useState(() => decodeUrlId(firstQuery.current.get('batch')));

  const [batches, setBatches] = useState([]);
  const [batchesLoading, setBatchesLoading] = useState(false);
  const [courses, setCourses] = useState([]);
  const [coursesLoading, setCoursesLoading] = useState(false);
  const [byFrom, setByFrom] = useState({});
  const [verify, setVerify] = useState(null);
  const [verifying, setVerifying] = useState(false);
  const [savingMap, setSavingMap] = useState(false);

  const [newBatchForm, setNewBatchForm] = useState({ academicName: '', startYear: '', endYear: '' });
  const [creating, setCreating] = useState(false);
  const [runs, setRuns] = useState([]);
  const [runsLoading, setRunsLoading] = useState(false);
  const [run, setRun] = useState(null);

  const [plan, setPlan] = useState(null);
  const [planLoading, setPlanLoading] = useState(false);
  const [planCourseId, setPlanCourseId] = useState(0);
  const [generating, setGenerating] = useState(false);
  const [savingItemId, setSavingItemId] = useState(0);
  const [applying, setApplying] = useState(false);
  const [reverting, setReverting] = useState(false);
  const [confirm, setConfirm] = useState(null);

  const sourceBatch = batches.find(el => el.batchId === sourceBatchId);
  const batchName = id => batches.find(el => el.batchId === id)?.name || (id ? `Batch ${id}` : '--');
  const progress = useMemo(() => classOrderProgress(courses, byFrom), [courses, byFrom]);
  // classes listed in the order a student moves through them (by id while no order is set)
  const orderedCourses = useMemo(() => sortByClassOrder(courses, byFrom), [courses, byFrom]);
  const done = doneSteps({ classOrderValid: verify?.valid, run });

  const goToStep = step => setActiveStep(clampStep(step));
  const askConfirm = (message, onYes) => setConfirm({ message, onYes });

  // the address carries the step, the request and the batch, so a reload (or a shared link) lands in the same place
  useEffect(() => {
    const params = new URLSearchParams();
    params.set('step', activeStep);
    if (run?.runId) params.set('run', encodeUrlId(run.runId));
    if (sourceBatchId) params.set('batch', encodeUrlId(sourceBatchId));
    history.replace(`${location.pathname}?${params.toString()}`);
  }, [activeStep, run?.runId, sourceBatchId]);

  const loadRuns = () => {
    setRunsLoading(true);
    return fetchPromotionRunsApi(api)
      .then(list => setRuns([...(list || [])].sort((a, b) => b.runId - a.runId)))
      .catch(toastError)
      .finally(() => setRunsLoading(false));
  };

  // the batch switch at the top lists the school's batches: a new or removed batch has to show up there too
  // (this page's own batch list too, or a just-created batch would show as "Batch 24" instead of its name)
  const refreshSchoolBatches = () => {
    fetchPromotionBatchesApi(api)
      .then(list => setBatches(list || []))
      .catch(() => {});
    return dispatch(fetchSchoolBatchsService({ token, schoolId }));
  };

  const loadPlan = async (runId, courseId = 0) => {
    setPlanLoading(true);
    try {
      const data = await fetchPromotionPlanApi({ ...api, runId, courseId });
      // a class's students come with the counts of every class; if the backend only sent that class, keep the full counts
      setPlan(prev =>
        courseId && prev?.summary?.length > (data.summary?.length || 0)
          ? { ...data, summary: prev.summary, totalStudents: prev.totalStudents, totalErrors: prev.totalErrors }
          : data
      );
    } catch (err) {
      handleRunError(err);
    } finally {
      setPlanLoading(false);
    }
  };

  const refreshRun = async runId => {
    const data = await fetchPromotionRunApi({ ...api, runId });
    setRun(data);
    return data;
  };

  const openRun = async (runId, { stay = false } = {}) => {
    try {
      const data = await refreshRun(runId);
      setSourceBatchId(data.sourceBatchId);
      setPlanCourseId(0);
      setPlan(null);
      if ([RUN_STATUS.planReady, RUN_STATUS.promoted].includes(data.status)) loadPlan(data.runId);
      if (!stay) goToStep(stepOfRun(data));
    } catch (err) {
      handleRunError(err);
    }
  };

  const clearRun = () => {
    setRun(null);
    setPlan(null);
    setPlanCourseId(0);
  };

  // the request can be gone: reverted or removed from another window or tab. Drop it and say so, instead of showing it still.
  const handleRunError = err => {
    if (!/promotion request not found/i.test(formResMessage(err))) {
      toastError(err);
      return;
    }
    clearRun();
    goToStep(1);
    loadRuns();
    refreshSchoolBatches();
    toast(
      'This promotion request no longer exists: it was reverted or removed. Start a new one or open another.',
      'warning'
    );
  };

  useEffect(() => {
    if (!schoolId) return;
    setBatchesLoading(true);
    fetchPromotionBatchesApi(api)
      .then(list => {
        setBatches(list || []);
        // start from the academic year that is running now, unless a request or the address already chose one
        setSourceBatchId(prev => {
          if (prev) return prev;
          const { startYear } = getCurrentYearBatchUtils();
          return (list || []).find(el => el.startYear === startYear)?.batchId || 0;
        });
      })
      .catch(toastError)
      .finally(() => setBatchesLoading(false));
    loadRuns();
    const runId = decodeUrlId(firstQuery.current.get('run'));
    if (runId) openRun(runId, { stay: true });
  }, []);

  const refreshOrder = async batchId => {
    const [map, check] = await Promise.all([
      fetchCourseMapApi(api),
      verifyCourseMapApi({ ...api, sourceBatchId: batchId }).catch(() => null),
    ]);
    setByFrom(indexCourseMap(map));
    setVerify(check);
  };

  useEffect(() => {
    if (!schoolId || !sourceBatchId) {
      setCourses([]);
      setByFrom({});
      setVerify(null);
      return undefined;
    }
    let cancelled = false;
    setCoursesLoading(true);
    Promise.all([fetchPromotionBatchCoursesApi({ ...api, batchId: sourceBatchId }), refreshOrder(sourceBatchId)])
      .then(([list]) => !cancelled && setCourses([...(list || [])].sort((a, b) => a.courseId - b.courseId)))
      .catch(err => !cancelled && toastError(err))
      .finally(() => !cancelled && setCoursesLoading(false));
    return () => {
      cancelled = true;
    };
  }, [sourceBatchId]);

  // the new batch is normally the year after the one promoted from; the admin can still change it
  useEffect(() => {
    if (sourceBatch) setNewBatchForm(suggestNextBatch(sourceBatch));
  }, [sourceBatch?.batchId, sourceBatch?.startYear]);

  const onVerify = async () => {
    setVerifying(true);
    try {
      setVerify(await verifyCourseMapApi({ ...api, sourceBatchId }));
    } catch (err) {
      toastError(err);
    } finally {
      setVerifying(false);
    }
  };

  const onSaveRows = async rows => {
    setSavingMap(true);
    try {
      for (const { courseId, value } of rows) {
        // eslint-disable-next-line no-await-in-loop
        await saveCourseMapApi({ ...api, mapId: byFrom[courseId]?.id, postData: courseMapBody(courseId, value) });
      }
      await refreshOrder(sourceBatchId);
      toast(rows.length > 1 ? `${rows.length} ${courseStatic.toLowerCase()} orders saved` : 'Saved');
    } catch (err) {
      toastError(err);
      refreshOrder(sourceBatchId).catch(() => {});
    } finally {
      setSavingMap(false);
    }
  };

  const onClearRow = courseId => {
    const mapId = byFrom[courseId]?.id;
    if (!mapId) return;
    askConfirm(`Clear the next ${courseStatic.toLowerCase()} of this ${courseStatic.toLowerCase()}?`, async () => {
      setSavingMap(true);
      try {
        await deleteCourseMapApi({ ...api, mapId });
        await refreshOrder(sourceBatchId);
      } catch (err) {
        toastError(err);
      } finally {
        setSavingMap(false);
      }
    });
  };

  const onCreate = async () => {
    setCreating(true);
    try {
      const data = await createPromotionRunApi({
        ...api,
        postData: {
          sourceBatchId,
          academicName: String(newBatchForm.academicName).trim(),
          startYear: Number(newBatchForm.startYear),
          endYear: Number(newBatchForm.endYear),
        },
      });
      setRun(data);
      setPlan(null);
      setPlanCourseId(0);
      toast(`New batch ${data.academicName || ''} created. Nobody is moved until you promote.`);
      goToStep(2);
      loadRuns();
      refreshSchoolBatches();
    } catch (err) {
      toastError(err);
    } finally {
      setCreating(false);
    }
  };

  const onGenerate = async () => {
    setGenerating(true);
    try {
      const data = await generatePromotionPlanApi({ ...api, runId: run.runId });
      setPlanCourseId(0);
      setPlan(data);
      await refreshRun(run.runId);
      loadRuns();
    } catch (err) {
      handleRunError(err);
    } finally {
      setGenerating(false);
    }
  };

  const onPickCourse = courseId => {
    setPlanCourseId(courseId);
    loadPlan(run.runId, courseId);
  };

  const onSaveItem = async (itemId, postData) => {
    setSavingItemId(itemId);
    try {
      await updatePromotionPlanItemApi({ ...api, runId: run.runId, itemId, postData });
      await loadPlan(run.runId, planCourseId);
    } catch (err) {
      handleRunError(err);
    } finally {
      setSavingItemId(0);
    }
  };

  const onApply = async () => {
    setApplying(true);
    try {
      const data = await applyPromotionRunApi({ ...api, runId: run.runId });
      setRun(data);
      toast('Students promoted into the new batch');
      goToStep(3);
      loadRuns();
      refreshSchoolBatches();
      loadPlan(data.runId, planCourseId);
    } catch (err) {
      handleRunError(err);
    } finally {
      setApplying(false);
    }
  };

  const onRevert = async () => {
    setReverting(true);
    try {
      const data = await revertPromotionRunApi({ ...api, runId: run.runId });
      if (data?.runId) {
        setRun(data);
        if (data.status === RUN_STATUS.created) setPlan(null);
        else loadPlan(data.runId, planCourseId);
        goToStep(stepOfRun(data));
      } else {
        clearRun();
        goToStep(1);
      }
      toast('Reverted');
      loadRuns();
      refreshSchoolBatches();
    } catch (err) {
      handleRunError(err);
    } finally {
      setReverting(false);
    }
  };

  const startAgain = () => {
    clearRun();
    goToStep(0);
  };

  if (!schoolId) {
    return (
      <div className="content">
        <EmptyState
          icon="fas fa-school"
          title="Select a school first"
          subtitle="Promotion works on one school at a time."
        />
      </div>
    );
  }

  const stepContent = [
    <ClassOrderStep
      key="order"
      batches={batches}
      batchesLoading={batchesLoading}
      sourceBatchId={sourceBatchId}
      onSourceChange={setSourceBatchId}
      courses={orderedCourses}
      coursesLoading={coursesLoading}
      byFrom={byFrom}
      progress={progress}
      verify={verify}
      verifying={verifying}
      onVerify={onVerify}
      onSaveRows={onSaveRows}
      onClearRow={onClearRow}
      savingMap={savingMap}
      openRequest={openRunOf(runs)}
      onOpenRun={openRun}
    />,
    <NewBatchStep
      key="batch"
      sourceBatch={sourceBatch}
      batches={batches}
      form={newBatchForm}
      onChange={(name, value) => setNewBatchForm(prev => ({ ...prev, [name]: value }))}
      onCreate={onCreate}
      creating={creating}
      verify={verify}
      runs={runs}
      runsLoading={runsLoading}
      batchName={batchName}
      currentRunId={run?.runId}
      onOpenRun={openRun}
      goToStep={goToStep}
    />,
    <PlanStep
      key="plan"
      run={run}
      plan={plan}
      planLoading={planLoading}
      planCourseId={planCourseId}
      onPickCourse={onPickCourse}
      onGenerate={onGenerate}
      generating={generating}
      courses={orderedCourses}
      onSaveItem={onSaveItem}
      savingItemId={savingItemId}
      askConfirm={askConfirm}
      goToStep={goToStep}
    />,
    <PromoteStep
      key="promote"
      run={run}
      plan={plan}
      targetName={run ? batchName(run.targetBatchId) : ''}
      onApply={onApply}
      applying={applying}
      askConfirm={askConfirm}
      goToStep={goToStep}
      onStartAgain={startAgain}
      onOpenStudents={() => history.push('/admin/school-students?school-students')}
    />,
  ];

  const canGoNext = activeStep === 0 ? !!sourceBatchId : !!run;

  return (
    <div className="content">
      <Card className="p-2 mb-3">
        <Stepper nonLinear activeStep={activeStep} alternativeLabel style={{ background: 'transparent' }}>
          {steps.map((label, index) => (
            <Step key={label} completed={done.has(index) && index !== activeStep}>
              <StepButton onClick={() => goToStep(index)}>{label}</StepButton>
            </Step>
          ))}
        </Stepper>
        <div style={{ padding: '0 16px 10px' }}>
          <LinearProgress
            variant="determinate"
            color="secondary"
            value={(done.size / steps.length) * 100}
            style={{ height: 6, borderRadius: 3, backgroundColor: '#f0eaf7' }}
          />
          <div style={{ fontSize: 12, color: '#8b95a1', marginTop: 4 }}>
            {done.size} of {steps.length} steps done
          </div>
        </div>
      </Card>

      {run && (
        <div
          style={{
            display: 'flex',
            flexWrap: 'wrap',
            alignItems: 'center',
            justifyContent: 'space-between',
            gap: 8,
            background: '#F5EDFB',
            padding: '8px 12px',
            borderRadius: 6,
            marginBottom: 16,
          }}>
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              flexWrap: 'wrap',
              gap: 8,
              fontWeight: 'bold',
              color: '#7B1FA2',
            }}>
            <CheckCircleIcon fontSize="small" />
            Promotion #{run.runId}: {batchName(run.sourceBatchId)} → {run.academicName}
            <StatusChip status={run.status} />
            {run.nextStep && (
              <span style={{ fontWeight: 'normal', fontSize: 12, color: '#6b778a' }}>Next: {run.nextStep}</span>
            )}
          </div>
          <Button
            size="small"
            variant="outlined"
            color="secondary"
            style={{ fontWeight: 'bold' }}
            disabled={!run.canRevert || reverting}
            onClick={() => askConfirm(revertMessage(run.status), onRevert)}>
            {revertLabel(run.status)}
          </Button>
          {!run.canRevert && !!run.revertBlockers?.length && (
            <ul style={{ flexBasis: '100%', color: '#c62828', fontSize: 12, margin: 0, paddingLeft: 20 }}>
              {run.revertBlockers.map(blocker => (
                <li key={blocker}>{blocker}</li>
              ))}
            </ul>
          )}
        </div>
      )}

      {stepContent[activeStep]}

      <div style={{ marginTop: 16, display: 'flex', justifyContent: 'space-between' }}>
        <CustomButton
          variant="outlined"
          name="← Back"
          disabled={activeStep === 0}
          onClick={() => goToStep(activeStep - 1)}
        />
        {activeStep < steps.length - 1 && (
          <CustomButton name="Next →" disabled={!canGoNext} onClick={() => goToStep(activeStep + 1)} />
        )}
      </div>
      {!canGoNext && activeStep < steps.length - 1 && (
        <div style={{ textAlign: 'right', fontSize: 12, color: '#8b95a1', marginTop: 6 }}>
          {activeStep === 0
            ? `Choose the batch to promote from to continue`
            : 'Create the new batch (or open a request) to continue'}
        </div>
      )}

      <ConfirmModal
        size="md"
        confirmModalOpen={!!confirm}
        confirmMessage={confirm?.message}
        deleteConfirm={() => {
          const onYes = confirm?.onYes;
          setConfirm(null);
          if (onYes) onYes();
        }}
        deleteCancel={() => setConfirm(null)}
      />
    </div>
  );
};

// Promoting a whole school is for the admins (school admin and super admin), not for teachers.
const PromotionPage = () => {
  const loggedUserRole = useSelector(state => state.auth.loggedUserRole);
  if (![constants.roles.admin, constants.roles.SA].includes(loggedUserRole)) {
    return (
      <div className="content">
        <EmptyState
          icon="fas fa-lock"
          title="Only an admin can promote students"
          subtitle="Ask an admin to run the year-end promotion."
        />
      </div>
    );
  }
  return <PromotionWizard />;
};

export default PromotionPage;
