import React, { useRef, useState } from 'react';
import Collapse from '@material-ui/core/Collapse';
import ExpandLessIcon from '@material-ui/icons/ExpandLess';
import ExpandMoreIcon from '@material-ui/icons/ExpandMore';
import { useChainWheel } from 'utils/useContainWheel';
import { Chip } from './StatusChip';

// The problems the backend found, folded away: one line with the count, and the list opens when it is clicked.
const IssueList = ({ title, issues }) => {
  const [open, setOpen] = useState(false);
  const listRef = useRef(null);
  useChainWheel(listRef);
  const toggle = () => setOpen(prev => !prev);
  const count = issues?.length || 0;

  return (
    <div style={{ marginBottom: 8 }}>
      <div
        role="button"
        tabIndex={0}
        aria-expanded={open}
        onClick={toggle}
        onKeyDown={e => (e.key === 'Enter' || e.key === ' ') && toggle()}
        style={{ display: 'inline-flex', alignItems: 'center', gap: 8, cursor: 'pointer', userSelect: 'none' }}>
        <Chip label={title} tone="bad" />
        {count > 0 && (
          <span style={{ fontSize: 13, color: '#c62828', fontWeight: 'bold' }}>
            {count} issue{count > 1 ? 's' : ''}
          </span>
        )}
        {count > 0 && (open ? <ExpandLessIcon fontSize="small" /> : <ExpandMoreIcon fontSize="small" />)}
      </div>
      {count > 0 && (
        <Collapse in={open} timeout="auto" unmountOnExit={false}>
          <ul
            ref={listRef}
            style={{
              color: '#c62828',
              fontSize: 13,
              margin: '8px 0 0',
              padding: '8px 12px 8px 30px',
              maxHeight: 220,
              overflowY: 'auto',
              background: '#fff5f5',
              border: '1px solid #f3d3d3',
              borderRadius: 6,
            }}>
            {issues.map(issue => (
              <li key={issue}>{issue}</li>
            ))}
          </ul>
        </Collapse>
      )}
    </div>
  );
};

export default IssueList;
