import React from 'react';
import { Card, Button } from '@material-ui/core';
import Table from '@material-ui/core/Table';
import TableBody from '@material-ui/core/TableBody';
import TableCell from '@material-ui/core/TableCell';
import TableContainer from '@material-ui/core/TableContainer';
import TableHead from '@material-ui/core/TableHead';
import TableRow from '@material-ui/core/TableRow';
import { Row, Col } from 'reactstrap';
import CheckCircleIcon from '@material-ui/icons/CheckCircle';
import CustomButton from 'components/CustomButton';
import CustomInput from 'views/admin/Common/CustomInput';
import EmptyState from 'views/admin/Common/EmptyState';
import { SkeletonRows } from 'views/admin/Common/Loader';
import colors from 'config/colors';
import { newBatchFormError, openRunOf } from 'utils/promotion';
import StatusChip from './StatusChip';
import StepHeader from './StepHeader';

const intro =
  'Create the batch the students move into. It is only created here: nobody is moved until you apply the plan in the last step.';

// Step 2: the new batch, plus every promotion request of the school (to carry on with one that is half done).
const NewBatchStep = ({
  sourceBatch,
  batches,
  form,
  onChange,
  onCreate,
  creating,
  verify,
  runs,
  runsLoading,
  batchName,
  currentRunId,
  onOpenRun,
  goToStep,
}) => {
  const formError = newBatchFormError({
    sourceBatchId: sourceBatch?.batchId,
    sourceStartYear: sourceBatch?.startYear,
    ...form,
  });
  // the backend lets only one promotion be open at a time
  const openRun = openRunOf(runs);
  const orderBroken = verify && verify.valid === false;
  // the backend refuses a batch whose start and end year the school already has
  const sameYearBatch = (batches || []).find(
    el => Number(el.startYear) === Number(form.startYear) && Number(el.endYear) === Number(form.endYear)
  );
  const blocked = !!formError || orderBroken || !!sameYearBatch || !!openRun;

  return (
    <>
      <Card className="p-3 mb-3">
        <StepHeader title="New batch" intro={intro} />
        {sourceBatch ? (
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: 8,
              background: '#F5EDFB',
              color: colors.accent,
              fontWeight: 'bold',
              padding: '8px 12px',
              borderRadius: 6,
              marginBottom: 16,
            }}>
            <CheckCircleIcon fontSize="small" /> Promoting from: {sourceBatch.name}
          </div>
        ) : (
          <div style={{ marginBottom: 16, fontSize: 13 }}>
            No batch to promote from yet.{' '}
            <a style={{ color: colors.aTag, cursor: 'pointer', fontWeight: 'bold' }} onClick={() => goToStep(0)}>
              Choose it in the first step
            </a>
          </div>
        )}
        <Row>
          <Col md={4}>
            <CustomInput
              label="New batch name"
              name="academicName"
              value={form.academicName}
              onChange={onChange}
              placeholder="2027 - 2028"
            />
          </Col>
          <Col md={2}>
            <CustomInput label="Start year" name="startYear" type="number" value={form.startYear} onChange={onChange} />
          </Col>
          <Col md={2}>
            <CustomInput label="End year" name="endYear" type="number" value={form.endYear} onChange={onChange} />
          </Col>
          <Col md={4} className="d-flex align-items-start" style={{ paddingTop: 29 }}>
            <CustomButton
              name="Create new batch"
              showLoader
              loading={creating}
              disabled={creating || blocked}
              onClick={onCreate}
            />
          </Col>
        </Row>
        {orderBroken ? (
          <div style={{ fontSize: 13, color: '#c62828' }}>
            The class order has problems, so the batch cannot be created yet.{' '}
            <a style={{ color: colors.aTag, cursor: 'pointer', fontWeight: 'bold' }} onClick={() => goToStep(0)}>
              Fix the class order
            </a>
          </div>
        ) : (
          !!sourceBatch && !!formError && <div style={{ fontSize: 13, color: '#b26a00' }}>{formError}</div>
        )}
        {!!openRun && (
          <div style={{ fontSize: 13, color: '#c62828', marginTop: 4 }}>
            Promotion #{openRun.runId} ({openRun.academicName}) is not finished yet. Finish or revert it before starting
            another.{' '}
            <a
              style={{ color: colors.aTag, cursor: 'pointer', fontWeight: 'bold' }}
              onClick={() => onOpenRun(openRun.runId)}>
              Open it
            </a>
          </div>
        )}
        {!!sameYearBatch && (
          <div style={{ fontSize: 13, color: '#c62828', marginTop: 4 }}>
            The school already has a batch for {sameYearBatch.startYear} to {sameYearBatch.endYear} (
            {sameYearBatch.name}). Change the years to create a new one.
          </div>
        )}
      </Card>

      <Card className="p-3">
        <StepHeader
          title="Promotion requests"
          intro="Open a request to carry on where you stopped, or to look at a finished one."
        />
        {runsLoading ? (
          <div style={{ padding: 20 }}>
            <SkeletonRows rows={2} avatar={false} />
          </div>
        ) : !runs.length ? (
          <EmptyState compact bare icon="fas fa-level-up-alt" title="No promotion requests yet" />
        ) : (
          <TableContainer>
            <Table size="small">
              <TableHead>
                <TableRow>
                  <TableCell>Request</TableCell>
                  <TableCell>Name</TableCell>
                  <TableCell>Years</TableCell>
                  <TableCell>From</TableCell>
                  <TableCell>To</TableCell>
                  <TableCell>Status</TableCell>
                  <TableCell align="right" />
                </TableRow>
              </TableHead>
              <TableBody>
                {runs.map(run => (
                  <TableRow key={run.runId} hover selected={run.runId === currentRunId}>
                    <TableCell>#{run.runId}</TableCell>
                    <TableCell style={{ fontWeight: 'bold' }}>{run.academicName}</TableCell>
                    <TableCell>
                      {run.startYear} - {run.endYear}
                    </TableCell>
                    <TableCell>{batchName(run.sourceBatchId)}</TableCell>
                    <TableCell>{run.targetBatchId ? batchName(run.targetBatchId) : '--'}</TableCell>
                    <TableCell>
                      <StatusChip status={run.status} />
                    </TableCell>
                    <TableCell align="right">
                      {run.status === 'LEGACY' ? (
                        <span style={{ fontSize: 12, color: '#8b95a1' }}>Created earlier</span>
                      ) : (
                        <Button
                          size="small"
                          variant="outlined"
                          color="secondary"
                          style={{ fontWeight: 'bold' }}
                          onClick={() => onOpenRun(run.runId)}>
                          {run.runId === currentRunId ? 'Continue' : 'Open'}
                        </Button>
                      )}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        )}
      </Card>
    </>
  );
};

export default NewBatchStep;
