import React, { useEffect, useMemo, useState } from 'react';
import { Card } from '@material-ui/core';
import Table from '@material-ui/core/Table';
import TableBody from '@material-ui/core/TableBody';
import TableCell from '@material-ui/core/TableCell';
import TableHead from '@material-ui/core/TableHead';
import TableRow from '@material-ui/core/TableRow';
import NativeSelect from '@material-ui/core/NativeSelect';
import { Row, Col } from 'reactstrap';
import CustomButton from 'components/CustomButton';
import CustomSelect from 'components/CustomSelect';
import colors from 'config/colors';
import { coursesStatic, courseStatic } from 'config/constants';
import EmptyState from 'views/admin/Common/EmptyState';
import { SkeletonRows } from 'views/admin/Common/Loader';
import { FINAL_CLASS, nextClassValue } from 'utils/promotion';
import { Chip } from './StatusChip';
import IssueList from './IssueList';
import ScrollTable from './ScrollTable';
import StepHeader from './StepHeader';

const intro = `Choose the batch to promote from, then the ${courseStatic.toLowerCase()} each ${courseStatic.toLowerCase()} moves up to. The last ${courseStatic.toLowerCase()} of the school is marked final: its students graduate. This is set once and reused every year.`;

// Step 1: each class's next class (the CoursePromotionMap), saved one row at a time or all together.
const ClassOrderStep = ({
  batches,
  batchesLoading,
  sourceBatchId,
  onSourceChange,
  courses,
  coursesLoading,
  byFrom,
  progress,
  verify,
  verifying,
  onVerify,
  onSaveRows,
  onClearRow,
  savingMap,
  openRequest,
  onOpenRun,
}) => {
  // Only the rows the admin changed; every other row shows what is saved.
  const [drafts, setDrafts] = useState({});
  useEffect(() => setDrafts({}), [courses, byFrom]);

  const valueOf = courseId => (courseId in drafts ? drafts[courseId] : nextClassValue(byFrom[courseId]));
  const dirtyIds = useMemo(
    () =>
      Object.keys(drafts)
        .filter(id => drafts[id] !== '' && drafts[id] !== nextClassValue(byFrom[id]))
        .map(Number),
    [drafts, byFrom]
  );

  const batchOptions = (batches || []).map(el => ({ ...el, label: el.name, value: el.batchId }));

  return (
    <Card className="p-3">
      <StepHeader title={`${courseStatic} order`} intro={intro} />
      <Row>
        <Col md={4}>
          <CustomSelect
            label="Promote from"
            name="sourceBatchId"
            value={sourceBatchId}
            loading={batchesLoading}
            // the menu goes to the page itself: inline it was drawn under the table's sticky header
            usePortal
            onChange={(name, value) => onSourceChange(value)}
            options={batchOptions}
          />
        </Col>
        <Col md={8} className="d-flex align-items-end justify-content-md-end" style={{ marginBottom: 2, gap: 8 }}>
          <CustomButton
            variant="outlined"
            name="Check order"
            showLoader
            loading={verifying}
            disabled={!sourceBatchId || verifying}
            onClick={onVerify}
          />
          <CustomButton
            name={dirtyIds.length ? `Save ${dirtyIds.length} change${dirtyIds.length > 1 ? 's' : ''}` : 'Save changes'}
            showLoader
            loading={savingMap}
            disabled={!dirtyIds.length || savingMap}
            onClick={() => onSaveRows(dirtyIds.map(id => ({ courseId: id, value: drafts[id] })))}
          />
        </Col>
      </Row>

      {!sourceBatchId ? (
        <EmptyState
          compact
          bare
          icon="fas fa-level-up-alt"
          title="Choose a batch to start"
          subtitle={`Its ${coursesStatic.toLowerCase()} are listed here with the ${courseStatic.toLowerCase()} each one moves up to.`}
        />
      ) : coursesLoading ? (
        <div style={{ padding: 20 }}>
          <SkeletonRows rows={4} avatar={false} />
        </div>
      ) : !courses.length ? (
        <EmptyState
          compact
          bare
          icon="fa fa-layer-group"
          title={`This batch has no active ${coursesStatic.toLowerCase()}`}
        />
      ) : (
        <>
          <div style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: 12, margin: '4px 0 8px' }}>
            <span style={{ fontSize: 13, color: '#6b778a' }}>
              <b style={{ color: colors.accent }}>{progress.configured}</b> of {progress.total}{' '}
              {coursesStatic.toLowerCase()} have a next {courseStatic.toLowerCase()} · <b>{progress.finalClasses}</b>{' '}
              final
            </span>
            {verify?.valid && <Chip label="Order is valid" tone="good" />}
          </div>
          {verify && !verify.valid && <IssueList title="Order has problems" issues={verify.issues} />}
          {!!openRequest && (
            <div style={{ fontSize: 13, color: '#b26a00', marginBottom: 8 }}>
              Promotion #{openRequest.runId} ({openRequest.academicName}) is not finished yet, so a{' '}
              {courseStatic.toLowerCase()} order cannot be cleared until it is finished or reverted.{' '}
              <a
                style={{ color: colors.aTag, cursor: 'pointer', fontWeight: 'bold' }}
                onClick={() => onOpenRun(openRequest.runId)}>
                Open it
              </a>
            </div>
          )}
          <ScrollTable maxHeight={520}>
            <Table size="small" stickyHeader>
              <TableHead>
                <TableRow>
                  <TableCell>{courseStatic}</TableCell>
                  <TableCell>Next {courseStatic.toLowerCase()}</TableCell>
                  <TableCell>Status</TableCell>
                  <TableCell align="right" />
                </TableRow>
              </TableHead>
              <TableBody>
                {courses.map(course => {
                  const saved = byFrom[course.courseId];
                  const value = valueOf(course.courseId);
                  const dirty = value !== nextClassValue(saved);
                  return (
                    <TableRow key={course.courseId} hover>
                      <TableCell style={{ fontWeight: 'bold', whiteSpace: 'nowrap' }}>{course.name}</TableCell>
                      <TableCell>
                        <NativeSelect
                          value={value}
                          style={{ minWidth: 240 }}
                          onChange={e => setDrafts(prev => ({ ...prev, [course.courseId]: e.target.value }))}>
                          <option value="">-- not set --</option>
                          <option value={FINAL_CLASS}>Final {courseStatic.toLowerCase()} (students graduate)</option>
                          {courses
                            .filter(other => other.courseId !== course.courseId)
                            .map(other => (
                              <option key={other.courseId} value={other.courseId}>
                                {other.name}
                              </option>
                            ))}
                        </NativeSelect>
                      </TableCell>
                      <TableCell>
                        {dirty ? (
                          <Chip label="Unsaved" tone="warn" />
                        ) : saved ? (
                          <Chip label="Saved" tone="good" />
                        ) : (
                          <Chip label="Not set" tone="bad" />
                        )}
                      </TableCell>
                      <TableCell align="right" style={{ whiteSpace: 'nowrap' }}>
                        <CustomButton
                          size="small"
                          name="Save"
                          disabled={!dirty || value === '' || savingMap}
                          onClick={() => onSaveRows([{ courseId: course.courseId, value }])}
                        />
                        {saved && (
                          <CustomButton
                            size="small"
                            className="ml-2"
                            variant="outlined"
                            name="Clear"
                            disabled={savingMap || !!openRequest}
                            onClick={() => onClearRow(course.courseId)}
                          />
                        )}
                      </TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>
          </ScrollTable>
        </>
      )}
    </Card>
  );
};

export default ClassOrderStep;
